CREATE TYPE "InventoryCountType" AS ENUM ('FULL','LOCATION','CATEGORY','CYCLE','LOT');
CREATE TYPE "InventoryCountStatus" AS ENUM ('DRAFT','IN_PROGRESS','SUBMITTED','RECOUNT_REQUIRED','APPROVED','POSTED','CANCELLED');
CREATE TYPE "InventoryCountLineStatus" AS ENUM ('NOT_COUNTED','COUNTED','RECOUNT_REQUIRED','ACCEPTED','EXCLUDED','CONFLICT');
CREATE TYPE "InventoryCountEntryMethod" AS ENUM ('MANUAL','BARCODE_SCAN','SKU_SEARCH','ITEM_SEARCH','IMPORT');
CREATE TYPE "InventoryCountAssignmentStatus" AS ENUM ('ASSIGNED','IN_PROGRESS','COMPLETED','REASSIGNED','CANCELLED');
CREATE TYPE "InventoryCountEventType" AS ENUM ('CREATED','STARTED','SCOPE_FROZEN','USER_ASSIGNED','ITEM_SCANNED','LINE_COUNTED','UNEXPECTED_ITEM_FOUND','MISPLACED_ITEM_FOUND','RECOUNT_REQUESTED','RECOUNT_COMPLETED','SUBMITTED','APPROVED','ADJUSTMENT_POSTED','CANCELLED');
ALTER TABLE "InventoryTransaction" ADD COLUMN "countLineId" UUID, ADD COLUMN "countSessionId" UUID;
CREATE TABLE "InventoryCountTemplate" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"countType" "InventoryCountType" NOT NULL,"configuration" JSONB NOT NULL,"includeDescendantLocations" BOOLEAN NOT NULL DEFAULT true,"includeInactiveItems" BOOLEAN NOT NULL DEFAULT false,"includeZeroBalanceItems" BOOLEAN NOT NULL DEFAULT false,"includeQuarantinedLots" BOOLEAN NOT NULL DEFAULT false,"createdById" TEXT NOT NULL,"archivedAt" TIMESTAMP(3),"archivedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "InventoryCountTemplate_organizationId_clinicLocationId_name_key" ON "InventoryCountTemplate"("organizationId","clinicLocationId","name"); CREATE INDEX "InventoryCountTemplate_organizationId_clinicLocationId_isAc_idx" ON "InventoryCountTemplate"("organizationId","clinicLocationId","isActive");
CREATE TABLE "InventoryCountSequence" ("organizationId" TEXT NOT NULL,"year" INTEGER NOT NULL,"nextValue" INTEGER NOT NULL DEFAULT 1,PRIMARY KEY("organizationId","year"));
CREATE TABLE "InventoryCountSession" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"number" TEXT NOT NULL,"countType" "InventoryCountType" NOT NULL,"status" "InventoryCountStatus" NOT NULL DEFAULT 'DRAFT',"templateId" UUID,"configurationSnapshot" JSONB NOT NULL,"expectedSnapshotAt" TIMESTAMP(3),"blindCount" BOOLEAN NOT NULL DEFAULT false,"requireAllLines" BOOLEAN NOT NULL DEFAULT true,"requireRecount" BOOLEAN NOT NULL DEFAULT true,"varianceQuantityThreshold" DECIMAL(20,6),"variancePercentThreshold" DECIMAL(10,4),"startedById" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"submittedById" TEXT,"submittedAt" TIMESTAMP(3),"approvedById" TEXT,"approvedAt" TIMESTAMP(3),"cancelledById" TEXT,"cancelledAt" TIMESTAMP(3),"cancellationReason" TEXT,"postedById" TEXT,"postedAt" TIMESTAMP(3),"postingIdempotencyKey" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InventoryCountSession_templateId_fkey" FOREIGN KEY("templateId") REFERENCES "InventoryCountTemplate"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "InventoryCountSession_organizationId_number_key" ON "InventoryCountSession"("organizationId","number"); CREATE UNIQUE INDEX "InventoryCountSession_organizationId_postingIdempotencyKey_key" ON "InventoryCountSession"("organizationId","postingIdempotencyKey"); CREATE INDEX "InventoryCountSession_organizationId_clinicLocationId_statu_idx" ON "InventoryCountSession"("organizationId","clinicLocationId","status");
CREATE TABLE "InventoryCountLine" ("id" UUID PRIMARY KEY,"sessionId" UUID NOT NULL,"itemId" UUID NOT NULL,"stockLocationId" UUID NOT NULL,"lotId" UUID,"itemNameSnapshot" TEXT NOT NULL,"skuSnapshot" TEXT,"barcodeSnapshot" JSONB,"baseUnitSnapshot" TEXT NOT NULL,"quantityPrecisionSnapshot" INTEGER NOT NULL DEFAULT 6,"lotNumberSnapshot" TEXT,"expirationSnapshot" DATE,"lotStatusSnapshot" "InventoryLotStatus","expectedQuantitySnapshot" DECIMAL(20,6) NOT NULL,"firstCountedQuantity" DECIMAL(20,6),"finalCountedQuantity" DECIMAL(20,6),"varianceQuantity" DECIMAL(20,6),"variancePercentage" DECIMAL(10,4),"status" "InventoryCountLineStatus" NOT NULL DEFAULT 'NOT_COUNTED',"countedById" TEXT,"countedAt" TIMESTAMP(3),"recountRequired" BOOLEAN NOT NULL DEFAULT false,"recountReason" TEXT,"notes" TEXT,"isUnexpected" BOOLEAN NOT NULL DEFAULT false,"isMisplaced" BOOLEAN NOT NULL DEFAULT false,"expectedStockLocationId" UUID,"postedTransactionId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InventoryCountLine_sessionId_fkey" FOREIGN KEY("sessionId") REFERENCES "InventoryCountSession"("id") ON UPDATE CASCADE,CONSTRAINT "InventoryCountLine_itemId_fkey" FOREIGN KEY("itemId") REFERENCES "CatalogItem"("id") ON UPDATE CASCADE);
CREATE UNIQUE INDEX "InventoryCountLine_sessionId_itemId_stockLocationId_lotId_key" ON "InventoryCountLine"("sessionId","itemId","stockLocationId","lotId"); CREATE INDEX "InventoryCountLine_sessionId_status_idx" ON "InventoryCountLine"("sessionId","status");
CREATE TABLE "InventoryCountEntry" ("id" UUID PRIMARY KEY,"countLineId" UUID NOT NULL,"attemptNumber" INTEGER NOT NULL,"quantity" DECIMAL(20,6) NOT NULL,"enteredById" TEXT NOT NULL,"enteredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"method" "InventoryCountEntryMethod" NOT NULL,"notes" TEXT,"deviceMetadata" JSONB,CONSTRAINT "InventoryCountEntry_countLineId_fkey" FOREIGN KEY("countLineId") REFERENCES "InventoryCountLine"("id") ON UPDATE CASCADE);
CREATE UNIQUE INDEX "InventoryCountEntry_countLineId_attemptNumber_key" ON "InventoryCountEntry"("countLineId","attemptNumber"); CREATE INDEX "InventoryCountEntry_countLineId_enteredAt_idx" ON "InventoryCountEntry"("countLineId","enteredAt");
CREATE TABLE "InventoryCountAssignment" ("id" UUID PRIMARY KEY,"sessionId" UUID NOT NULL,"assignedUserId" TEXT NOT NULL,"stockLocationId" UUID,"filterSnapshot" JSONB,"status" "InventoryCountAssignmentStatus" NOT NULL DEFAULT 'ASSIGNED',"assignedById" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "InventoryCountAssignment_sessionId_fkey" FOREIGN KEY("sessionId") REFERENCES "InventoryCountSession"("id") ON UPDATE CASCADE);
CREATE INDEX "InventoryCountAssignment_sessionId_assignedUserId_status_idx" ON "InventoryCountAssignment"("sessionId","assignedUserId","status");
CREATE TABLE "InventoryCountEvent" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"sessionId" UUID NOT NULL,"lineId" UUID,"type" "InventoryCountEventType" NOT NULL,"actorId" TEXT NOT NULL,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventoryCountEvent_sessionId_fkey" FOREIGN KEY("sessionId") REFERENCES "InventoryCountSession"("id") ON UPDATE CASCADE);
CREATE INDEX "InventoryCountEvent_organizationId_clinicLocationId_created_idx" ON "InventoryCountEvent"("organizationId","clinicLocationId","createdAt"); CREATE INDEX "InventoryCountEvent_sessionId_createdAt_idx" ON "InventoryCountEvent"("sessionId","createdAt");
